def cmp_semver(a, b):
    def _is_numeric_identifier(s):
        return bool(s) and all(c in '0123456789' for c in s)

    def _parse(v):
        v = v.strip().split('+', 1)[0]
        core, sep, pre = v.partition('-')

        parts = core.split('.')
        if len(parts) < 3:
            parts += ['0'] * (3 - len(parts))
        if len(parts) > 3:
            parts = parts[:3]

        major, minor, patch = (int(p) if p else 0 for p in parts)
        pre_ids = None if not sep or pre == '' else pre.split('.')
        return (major, minor, patch), pre_ids

    a_core, a_pre = _parse(a)
    b_core, b_pre = _parse(b)

    if a_core != b_core:
        return -1 if a_core < b_core else 1

    if a_pre is None and b_pre is None:
        return 0
    if a_pre is None:
        return 1
    if b_pre is None:
        return -1

    for x, y in zip(a_pre, b_pre):
        x_num = _is_numeric_identifier(x)
        y_num = _is_numeric_identifier(y)

        if x_num and y_num:
            xi = int(x)
            yi = int(y)
            if xi != yi:
                return -1 if xi < yi else 1
        elif x_num != y_num:
            return -1 if x_num else 1
        else:
            if x != y:
                return -1 if x < y else 1

    if len(a_pre) != len(b_pre):
        return -1 if len(a_pre) < len(b_pre) else 1

    return 0

