def parse_range(header, size):
    import re

    if isinstance(header, (bytes, bytearray)):
        try:
            header = header.decode("ascii")
        except UnicodeDecodeError:
            return None
    if not isinstance(header, str):
        return None

    if isinstance(size, bool):
        return None
    if isinstance(size, float) and not size.is_integer():
        return None
    try:
        size = int(size)
    except (TypeError, ValueError, OverflowError):
        return None
    if size < 0:
        return None

    match = re.match(
        r"^\s*bytes\s*=\s*(.*)\s*$",
        header,
        re.IGNORECASE | re.ASCII | re.DOTALL,
    )
    if not match:
        return None

    value = match.group(1).strip()
    if not value:
        return None

    ranges = []
    for part in value.split(","):
        spec = part.strip()
        if not spec:
            return None

        spec_match = re.fullmatch(r"(\d*)-(\d*)", spec, re.ASCII)
        if not spec_match:
            return None

        first_s, last_s = spec_match.groups()
        if first_s == "" and last_s == "":
            return None

        if first_s == "":
            length = int(last_s)
            if size == 0:
                continue
            if length >= size:
                ranges.append((0, size - 1))
            elif length > 0:
                ranges.append((size - length, size - 1))
        else:
            start = int(first_s)
            if start >= size:
                continue

            if last_s == "":
                end = size - 1
            else:
                end = min(int(last_s), size - 1)

            if end >= start:
                ranges.append((start, end))

    return ranges if ranges else None

